#: **THE NAMES THIS MODULE CANNOT SERVE, each with the reason it cannot.**  Reading 10: "a
#: name with no schema subject gets a migration note and never a class".  Served as an
#: `AttributeError` carrying the reason, so `from adcp.types.capabilities import X` fails where the name has
#: no subject and says WHY, rather than resolving to something that silently is not what the
#: caller asked for.
__adcp_refused__ = {
    "Accreditation": "DOCUMENT-NO-WORD-NO-IDENTITY",
    "ExperimentalFeature": "DOCUMENT-NO-WORD-NO-IDENTITY",
    "GeoPostalAreas": "DOCUMENT-NO-WORD-NO-IDENTITY",
    "Metric": "DOCUMENT-NO-WORD-NO-IDENTITY",
    "SiCapabilities": "DOCUMENT-NO-WORD-NO-IDENTITY",
    "Specialism": "DOCUMENT-NO-WORD-NO-IDENTITY",
    "Transport": "DOCUMENT-NO-WORD-NO-IDENTITY",
}


def __getattr__(name: str) -> object:
    why = __adcp_refused__.get(name)
    if why is None:
        raise AttributeError(f"module {__name__!r} has no attribute {name!r}")
    raise AttributeError(
        f"{__name__}.{name} is upstream's and has no subject in the pinned bundle: {why}. "
        f"See docs/migration-from-upstream.md"
    )
